using System;
using System.Text;
using UnityEngine;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckBaseJumping {
public enum BaseJumpPhase {Intro,Flight,RoundResult,Complete}
public sealed class BaseJumpMatch:SportsEventSession {
 public override bool CompactViewportHud=>true;
 public override bool SupportsSplitAIViews=>true;
 public override bool TryReadViewportCard(int view,out int participant,out string score,out string detail){participant=-1;score=detail=null;if(view<0||view>=cameras.Length||view>=viewSlots.Length)return false;participant=viewSlots[view];if(participant<0||participant>=totals.Length)return false;score=totals[participant].ToString();detail="";return true;}
 public BaseSkyField skyField;public BaseJumpTransport transport;public BaseJumper[] jumpers;public SportsEventCamera[] views;public BaseJumpWeather weatherField;public Collider ground;public Transform target,helicopter,mainRotor,tailRotor;public AudioSource rotorAudio;public float targetRadius=16;public int seed=4757;
 public BaseJumpPhase Phase{get;private set;}public int Round{get;private set;}public int Winner{get;private set;}=-1;public float AirTime{get;private set;}public int LandingLocks{get;private set;}public int RoundLocks{get;private set;}public int[] totals=new int[4],totalErrors=new int[4],totalTimes=new int[4];public readonly int[] viewSlots={0,1,2,3};public int ViewCount{get;private set;}public bool Spectating{get;private set;}
 readonly BaseLanding[] roundResults=new BaseLanding[4];readonly int[] order=new int[4];readonly float[] deployHeight=new float[4],reactionAt=new float[4];readonly Vector2[] aiCommand=new Vector2[4],aimBias=new Vector2[4],windBias=new Vector2[4];readonly float[] responseGain=new float[4];readonly bool[] aiDeploy=new bool[4],aiHeld=new bool[4];float timer;readonly StringBuilder text=new StringBuilder(1200);
 public override string Title=>"TRUCK BASE JUMPING";public override int MinimumPlayers=>4;public override int MaximumPlayers=>4;public override bool MultiViewHUD=>true;public override string OptionLabel=>weatherField!=null&&weatherField.presentation!=null?(option==0?"WIND · STRONG CROSSWIND":option==1?"WIND · STRONG GUSTS":"WIND · REVERSE CROSSWIND"):(option==0?"STRONG CROSSWIND":option==1?"GUSTY STORM":"HEAVY SNOW / BLIZZARD");
 public override string Help=>"TRUCK BASE JUMPING · FOUR TRUCKS, ONE SHARED WEATHER FIELD\nThree rounds. One to four humans plus AI, or four-AI spectator mode. The four trucks wiggle, shuffle and hop through the real cargo opening in rotating order. Each has the same physical exit, altitude and initial velocity; its own flight timer starts at exit.\n\nMovement is compass aligned: left/right across the field, forward/back north/south. Freefall permits bounded air steering and pitch. ACTION deploys once: your shown keyboard key, whole-pad South, shared-left LT or shared-right RT. Release it after opening, then hold it again to FLARE / BRAKE. The canopy opens progressively; velocity never snaps to zero. Too-late or missed deployment risks a crash.\n\nThe same wind field drives every competitor. Canopies feel much stronger drift. Early opening gives more aiming time and more wind exposure; late opening is faster and riskier. Flare slows descent and horizontal motion but cannot hover.\n\nFIRST ground contact locks body-center landing error/time and incoming descent/attitude. Safe requires an open canopy, descent <=8m/s, horizontal speed <=12m/s and upright attitude. Driving/sliding afterward cannot improve it. No competitor collisions or blocking landed trucks. Escaping the field or 110 active seconds without landing is invalid.\n\nROUND RANKING: safe INSIDE the marked target beats safe outside. Within each category, compare ONE-METRE accuracy bands, then faster landing time, then exact error. Distances are stored to 1 mm and shown in feet/inches; times to 1 ms. Valid places award 4/3/2/1; crashes earn0. Exact round ties share place/points. Overall: total points, then lower total valid error, then lower total valid time; another four-truck round if still tied.\n\nPause/disconnect preserves flight, canopy, weather time and scores. Release controls and confirm freshly after reconnect or replacement. Rematch retains names, colors, sources and AI levels. Offline only.";
 public override string Header=>Title+" · ROUND "+Round+(Round<=3?" / 3":" · EXTRA");public override string Status=>Phase==BaseJumpPhase.Intro?"HELICOPTER RELEASE IN "+Mathf.CeilToInt(4-timer):Phase==BaseJumpPhase.Flight?"DEPLOY ONCE · RELEASE, THEN HOLD ACTION TO FLARE":"ACCURACY BAND → TIME → EXACT ERROR";
 public override string Standings{get{text.Clear();for(int i=0;i<4;i++)text.Append(setup.players[i].name).Append("  ").Append(totals[i]).Append(" PTS  ").Append(jumpers[i].Landed?jumpers[i].Outcome:jumpers[i].Deployed?"CANOPY":"FREEFALL").Append('\n');return text.ToString();}}
 public int ResultPlace(int slot){if(slot<0||slot>=4)throw new ArgumentOutOfRangeException(nameof(slot));if(Winner==slot)return 1;int place=1;for(int i=0;i<4;i++){if(i==slot)continue;if(i==Winner||totals[i]>totals[slot]||totals[i]==totals[slot]&&(totalErrors[i]<totalErrors[slot]||totalErrors[i]==totalErrors[slot]&&totalTimes[i]<totalTimes[slot]))place++;}return place;} public BaseLanding ResultLanding(int slot)=>roundResults[slot];
 public override string Results{get{text.Clear().Append(setup.players[Winner].name).Append(" WINS\n\n");for(int i=0;i<4;i++)text.Append(setup.players[i].name).Append("   ").Append(totals[i]).Append(" PTS   VALID ERROR ").Append(BaseJumpRules.Distance(totalErrors[i])).Append("   TIME ").Append((totalTimes[i]/1000f).ToString("F3")).Append("s\n");text.Append("\nFinal round: inside target > metre band > time > exact error.\n");AppendRound();return text.ToString();}}
 void AppendRound(){for(int k=0;k<4;k++){int i=order[k];var r=roundResults[i];text.Append(setup.players[i].name).Append("   ").Append(r.valid?(r.inside?"IN":"OUT")+" · BAND "+r.Band+"–"+(r.Band+1)+"m · "+BaseJumpRules.Distance(r.errorMillimetres)+" · "+(r.timeMilliseconds/1000f).ToString("F3")+"s · "+r.points+"pts":"INVALID · 0pts").Append('\n');}}
 public override string ViewText(int view){int slot=viewSlots[view];if(Spectating){slot=NextSpectator();viewSlots[0]=slot;}var j=jumpers[slot];text.Clear().Append("<color=#").Append(ColorUtility.ToHtmlStringRGB(setup.players[slot].color)).Append(">").Append(setup.players[slot].name).Append("</color> · R").Append(Round).Append(" · ").Append(totals[slot]).Append(" PTS").Append('\n');if(Phase==BaseJumpPhase.Intro)text.Append("HELICOPTER · RELEASE IN ").Append(Mathf.Max(1,Mathf.CeilToInt(4-timer)));else if(j.Landed){var r=j.Landing;text.Append(j.Outcome).Append(" · ").Append(BaseJumpRules.Distance(r.errorMillimetres)).Append(" · BAND ").Append(r.Band).Append("–").Append(r.Band+1).Append("m · ").Append((r.timeMilliseconds/1000f).ToString("F2")).Append("s");}else{var p=j.truck.body.position;text.Append(j.Outcome).Append(" · ALT ").Append(Mathf.RoundToInt(Mathf.Max(0,p.y)*3.28084f)).Append("ft · DOWN ").Append(Mathf.Max(0,-j.Incoming.y).ToString("F1")).Append("m/s\n").Append("TARGET ").Append(BaseJumpRules.Distance(Mathf.RoundToInt(new Vector2(p.x,p.z).magnitude*1000))).Append(" TO ").Append(Bearing(-p)).Append(" · WIND ").Append(Mathf.RoundToInt(weatherField.Flow.magnitude*2.23694f)).Append("mph TO ").Append(Bearing(weatherField.Flow)).Append(p.y<55&&!j.Deployed?" · LOW! DEPLOY ":" · ").Append(!j.Deployed?Controls(slot):"RELEASE THEN HOLD ACTION TO FLARE");}text.Append('\n');for(int i=0;i<4;i++)text.Append(i==0?"":"   ").Append("P").Append(i+1).Append(' ').Append(totals[i]);return text.ToString();}
 static readonly string[] Compass={"N","NE","E","SE","S","SW","W","NW"};static string Bearing(Vector3 v)=>Compass[Mathf.RoundToInt(Mathf.Repeat(Mathf.Atan2(v.x,v.z)*Mathf.Rad2Deg,360)/45)%8];
 protected override void BeginGame(){Array.Clear(totals,0,4);Array.Clear(totalErrors,0,4);Array.Clear(totalTimes,0,4);Round=1;LandingLocks=RoundLocks=0;Winner=-1;seed=UnityEngine.Random.Range(1,1000000);Layout();NewRound();}
 public void Layout(){ViewCount=SportsCameraOptions.Select(setup,viewSlots);Spectating=ViewCount==0;if(Spectating){ViewCount=1;viewSlots[0]=0;}weatherField.vendor.AllowCameras.Clear();for(int i=0;i<4;i++){views[i].view.enabled=i<ViewCount;views[i].view.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(ViewCount,i);if(i<ViewCount)weatherField.vendor.AllowCameras.Add(views[i].view);}}
 public static Vector3 ReleasePosition(int index){float a=(index-1.5f)*8*Mathf.Deg2Rad;return new Vector3(Mathf.Sin(a)*55,260,-Mathf.Cos(a)*55);}
 void NewRound(){timer=AirTime=0;Phase=BaseJumpPhase.Intro;weatherField.Select(option,seed+Round*997);weatherField.Tick(0);skyField?.ResetField(seed+Round*997);for(int i=0;i<4;i++){jumpers[i].Prepare(transport!=null?transport.Stage(i):ReleasePosition((i+Round-1)%4));jumpers[i].truck.body.maxAngularVelocity=5;float error=setup.players[i].difficulty==BowlingDifficulty.Easy?25:setup.players[i].difficulty==BowlingDifficulty.Normal?12:5;deployHeight[i]=(setup.players[i].difficulty==BowlingDifficulty.Easy?140:setup.players[i].difficulty==BowlingDifficulty.Normal?100:75)+UnityEngine.Random.Range(-error,error);var rng=new System.Random(seed+Round*1009+i*137);float spread=setup.players[i].difficulty==BowlingDifficulty.Easy?13:setup.players[i].difficulty==BowlingDifficulty.Normal?7:2.8f;float angle=(float)rng.NextDouble()*Mathf.PI*2;float magnitude=spread*(.3f+(float)rng.NextDouble()*.7f);aimBias[i]=new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))*magnitude;windBias[i]=new Vector2((float)rng.NextDouble()*2-1,(float)rng.NextDouble()*2-1)*(spread*.34f);responseGain[i]=.65f+(float)rng.NextDouble()*.3f;reactionAt[i]=0;aiCommand[i]=Vector2.zero;aiDeploy[i]=aiHeld[i]=false;for(int k=0;k<i;k++)Physics.IgnoreCollision(jumpers[i].truck.shape,jumpers[k].truck.shape);}Gate();feedback.Play(4,0,true);}
 public void LandingLocked(BaseJumper jumper){LandingLocks++;var r=jumper.Landing;Debug.Log("BASE_LANDING round="+Round+" slot="+jumper.slot+" valid="+r.valid+" inside="+r.inside+" errorMM="+r.errorMillimetres+" timeMS="+r.timeMilliseconds+" down="+r.verticalSpeed+" planar="+r.planarSpeed+" up="+r.up);}
 void AI(int i){var j=jumpers[i];if(!j.Released||Time.time<reactionAt[i])return;var level=setup.players[i].difficulty;float reaction=level==BowlingDifficulty.Easy?.62f:level==BowlingDifficulty.Normal?.32f:.16f;var p=j.truck.body.position;var v=j.truck.body.linearVelocity;var targetError=aimBias[i]-new Vector2(p.x,p.z);var desired=Vector2.ClampMagnitude(targetError*(j.Deployed?.22f:.12f),7.2f);float coupling=Mathf.Lerp(.18f,.65f,j.Opening),power=Mathf.Lerp(3.2f,8.5f,j.Opening);var estimatedWind=new Vector2(weatherField.Flow.x,weatherField.Flow.z)*responseGain[i]+windBias[i];var input=(desired-estimatedWind)*coupling/power+(desired-new Vector2(v.x,v.z))*.08f;aiCommand[i]=Vector2.ClampMagnitude(input,1);aiDeploy[i]=!j.Deployed&&p.y<=deployHeight[i];aiHeld[i]=aiDeploy[i]||j.Deployed&&p.y<18&&-j.Incoming.y>5.2f;reactionAt[i]=Time.time+reaction;}
 protected override void Simulate(float dt){timer+=dt;if(Phase==BaseJumpPhase.Intro){if(timer>=4){Phase=BaseJumpPhase.Flight;timer=AirTime=0;if(transport==null)for(int i=0;i<4;i++)jumpers[i].Release();feedback.Play(4,0,true);}return;}if(Phase==BaseJumpPhase.Flight){AirTime+=dt;weatherField.Tick(AirTime);skyField?.Step(dt,weatherField.Flow);bool all=true;for(int i=0;i<4;i++){var j=jumpers[i];if(j.Landed)continue;all=false;if(!j.Released&&transport!=null){int exitOrder=(i-(Round-1)%4+4)%4;transport.StageTruck(j,exitOrder,AirTime);if(AirTime>=transport.ExitAge(exitOrder))j.Release();else continue;}bool ai=setup.players[i].source==BowlingSource.AI;if(ai)AI(i);j.Step(ai?aiCommand[i]:commands[i],ai?aiDeploy[i]:actions[i],ai?aiHeld[i]:ActionHeld(i),dt,weatherField.Flow);if(ai&&j.Deployed)aiDeploy[i]=false;}if(all)FinishRound();}else if(Phase==BaseJumpPhase.RoundResult&&timer>4){if(Round>=3){Winner=BaseJumpRules.Winner(totals,totalErrors,totalTimes);if(Winner>=0){Phase=BaseJumpPhase.Complete;EndMatch();return;}}Round++;NewRound();}}
 void FinishRound(){if(Phase!=BaseJumpPhase.Flight)return;for(int i=0;i<4;i++)roundResults[i]=jumpers[i].Landing;BaseJumpRules.Rank(roundResults,order);for(int i=0;i<4;i++){var r=roundResults[i];jumpers[i].AssignRank(r);totals[i]+=r.points;if(r.valid){totalErrors[i]+=r.errorMillimetres;totalTimes[i]+=r.timeMilliseconds;}}RoundLocks++;Phase=BaseJumpPhase.RoundResult;timer=0;feedback.Play(5,0,true);Debug.Log("BASE_ROUND round="+Round+" scores="+string.Join(",",totals));}
 int NextSpectator(){int start=(int)(Time.time/5)%4;for(int i=0;i<4;i++){int slot=(start+i)%4;if(!jumpers[slot].Landed)return slot;}return start;}
 protected override void Present(float dt){if(jumpers==null||views==null)return;for(int i=0;i<4;i++)jumpers[i].Draw(dt);if(transport!=null)transport.AnimateRotors(dt);if(mainRotor!=null)mainRotor.Rotate(Vector3.up,1100*dt,Space.Self);if(tailRotor!=null)tailRotor.Rotate(Vector3.right,1400*dt,Space.Self);for(int v=0;v<ViewCount;v++){int slot=Spectating?NextSpectator():viewSlots[v];viewSlots[v]=slot;var p=jumpers[slot].truck.body.position;if(Phase==BaseJumpPhase.Intro||!jumpers[slot].Released)views[v].Pose(new Vector3(0,266,-31),new Vector3(46,22,-55),64);else if(jumpers[slot].Landed)views[v].Pose(Vector3.Lerp(p,target.position,.4f),new Vector3(14,10,-18),62);else{float open=jumpers[slot].Opening;var focus=p+Vector3.down*Mathf.Lerp(17,3,open);var offset=Vector3.Lerp(new Vector3(0,29,-12),new Vector3(0,13,-16),open);views[v].Pose(focus,offset,Mathf.Lerp(76,67,open),jumpers[slot].FlightTime<.12f);}}if(rotorAudio!=null){rotorAudio.volume=Live&&(Phase==BaseJumpPhase.Intro||Phase==BaseJumpPhase.Flight&&AirTime<9)&&Application.isFocused?settings.sfx*.08f:0;if(rotorAudio.volume>0&&!rotorAudio.isPlaying)rotorAudio.Play();else if(rotorAudio.volume<=0)rotorAudio.Stop();}}
 protected override void SetPaused(bool paused){weatherField?.PauseVisuals(paused);}
 protected override void StopGame(){skyField?.StopField();if(jumpers!=null)foreach(var j in jumpers){j.truck.Power(false);if(!j.truck.body.isKinematic)j.truck.body.linearVelocity=j.truck.body.angularVelocity=Vector3.zero;j.truck.body.isKinematic=true;}}
 protected override void StopSounds(){if(rotorAudio!=null)rotorAudio.Stop();if(jumpers!=null)foreach(var j in jumpers)j.truck.StopSound();}
}
}
